package com.creditsense.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="loan_applications") public class LoanApplication { @Id private UUID id=UUID.randomUUID(); @ManyToOne @JoinColumn(name="applicant_id",nullable=false) private Applicant applicant; @Column(name="amount_requested") private BigDecimal amountRequested; @Column(nullable=false) private String purpose; @Column(name="feature_vector",columnDefinition="jsonb") @org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.JSON) private String featureVector="{}"; @Enumerated(EnumType.STRING) private AppStatus status=AppStatus.SUBMITTED; @Column(name="submitted_at") private Instant submittedAt=Instant.now(); @Column(name="updated_at") private Instant updatedAt=Instant.now(); @Column(name="decision_reason") private String decisionReason; @Column(name="kyc_documents",columnDefinition="jsonb") @org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.JSON) private String kycDocuments="[]"; @Column(name="consent_at") private Instant consentAt; public LoanApplication(){} public UUID getId(){return id;} public Applicant getApplicant(){return applicant;} public BigDecimal getAmountRequested(){return amountRequested;} public String getPurpose(){return purpose;} public String getFeatureVector(){return featureVector;} public AppStatus getStatus(){return status;} public String getDecisionReason(){return decisionReason;} public void setApplicant(Applicant v){applicant=v;} public void setAmountRequested(BigDecimal v){amountRequested=v;} public void setPurpose(String v){purpose=v;} public void setFeatureVector(String v){featureVector=v;} public void setStatus(AppStatus v){status=v;} public void setUpdatedAt(Instant v){updatedAt=v;} public void setDecisionReason(String v){decisionReason=v;} public String getKycDocuments(){return kycDocuments;} public void setKycDocuments(String v){kycDocuments=v;} public Instant getConsentAt(){return consentAt;} public void setConsentAt(Instant v){consentAt=v;} public Instant getSubmittedAt(){return submittedAt;} public Instant getUpdatedAt(){return updatedAt;} }
